{
  "name": "eslint-config-next",
  "version": "16.3.6",
  "description": "ESLint configuration used by Next.js.",
  "license": "MIT",
  "repository": {
    "url": "vercel/next.js",
    "directory": "packages/eslint-config-next"
  },
  "homepage": "https://nextjs.org/docs/app/api-reference/config/eslint",
  "files": [
    "dist"
  ],
  "dependencies": {
    "@next/eslint-plugin-next": "16.3.6",
    "eslint-import-resolver-node": "^0.3.6",
    "eslint-import-resolver-typescript": "^3.5.2",
    "eslint-plugin-import": "^2.32.0",
    "eslint-plugin-jsx-a11y": "^6.10.0",
    "eslint-plugin-react": "^7.37.0",
    "eslint-plugin-react-hooks": "^7.0.0",
    "globals": "16.4.0",
    "typescript-eslint": "^8.46.0"
  },
  "peerDependencies": {
    "eslint": ">=9.0.0",
    "typescript": ">=3.3.1"
  },
  "peerDependenciesMeta": {
    "typescript": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/eslint": "9.6.1",
    "@types/eslint-plugin-jsx-a11y": "6.10.1",
    "typescript": "6.0.2"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./core-web-vitals": {
      "types": "./dist/core-web-vitals.d.ts",
      "default": "./dist/core-web-vitals.js"
    },
    "./typescript": {
      "types": "./dist/typescript.d.ts",
      "default": "./dist/typescript.js"
    },
    "./parser": {
      "types": "./dist/parser.d.ts",
      "default": "./dist/parser.js"
    }
  },
  "scripts": {
    "dev": "pnpm build",
    "build": "swc -d dist src && pnpm types",
    "types": "tsc --skipLibCheck --declaration --emitDeclarationOnly --esModuleInterop --declarationDir dist --rootDir src",
    "pack-for-isolated-tests": "pnpm pack --out ./packed.tgz"
  }
}
